CREATE COLUMN TABLE "TEST_AP"."UIVQ" ("TreeID" INTEGER CS_INT DEFAULT 0, "ParentID" INTEGER CS_INT DEFAULT -1, "LocType" SMALLINT CS_INT, "LocCode" NVARCHAR(8), "TransSeq" INTEGER CS_INT NOT NULL , "LayerID" INTEGER CS_INT NOT NULL , "OpenQty" DECIMAL(21,6) CS_FIXED, "OpenValue" DECIMAL(21,6) CS_FIXED, "ItemCode" NVARCHAR(50), "AbsEntry" INTEGER CS_INT NOT NULL , "StockActio" INTEGER CS_INT DEFAULT -1, "RemMethod" NVARCHAR(1) DEFAULT 'U', PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
ALTER TABLE "TEST_AP"."UIVQ" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$TreeID$OpenQty$','TreeID','OpenQty'));
CREATE UNIQUE INDEX "UIVQ_TRANS_SEQ" ON "TEST_AP"."UIVQ" ( "TransSeq" ASC, "LayerID" ASC );
CREATE INDEX "UIVQ_TreeOpenQt" ON "TEST_AP"."UIVQ" ( "TreeID" ASC, "OpenQty" ASC )